// several thing types come in consecutive variants that are picked at random
inline constexpr MobjType MobjVariant(const MobjType first, const int32_t offset) noexcept
{
	return static_cast<MobjType>(std::to_underlying(first) + offset);
}

enum struct InfightingGroup : int32_t
{
	Default,
	End
};

